    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    for t in seq(0, tsteps):
        # Sweep 1: update B from A (Jacobi step on A).
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                B[i, j] = 0.2 * (
                    A[i, j]
                    + A[i, j - 1]
                    + A[i, j + 1]
                    + A[i + 1, j]
                    + A[i - 1, j]
                )

        # Sweep 2: update A from B (Jacobi step on B).
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                A[i, j] = 0.2 * (
                    B[i, j]
                    + B[i, j - 1]
                    + B[i, j + 1]
                    + B[i + 1, j]
                    + B[i - 1, j]
