from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Base Jacobi-2D kernel written in Exo object code.
# We use 0-based loop indices (0 .. n-3) and shift accesses by +1 so that
# the interior points [1 .. n-2] are updated. This keeps loop lower bounds
# at 0, which makes loop tiling and other transformations simpler.
@proc
def kernel_jacobi_2d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    # Time stepping loop. Each iteration performs one Jacobi update,
    # alternating between A -> B and B -> A.
    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # Phase 1: Update B from A.
        # i, j iterate over 0 .. n-3, corresponding to interior cells
        # (i+1, j+1) in the original formulation.
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                B[i + 1, j + 1] = 0.2 * (
                    A[i + 1, j + 1]       # center
                    + A[i + 1, j]         # left   (j-1)
                    + A[i + 1, j + 2]     # right  (j+1)
                    + A[i + 2, j + 1]     # down   (i+1)
                    + A[i,     j + 1]     # up     (i-1)
                )

        # ------------------------------------------------------------------
        # Phase 2: Update A from B using the same 5-point stencil.
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                A[i + 1, j + 1] = 0.2 * (
                    B[i + 1, j + 1]
                    + B[i + 1, j]
                    + B[i + 1, j + 2]
                    + B[i + 2, j + 1]
                    + B[i,     j + 1]
                )


# ----------------------------------------------------------------------
# Scheduling: optimize for data locality and parallelism.
#
# - Tile the spatial loops (i, j) for both A- and B-update phases.
#   This improves cache locality by working on sub-blocks of the grid.
# - Parallelize the outer tile loops over i for both phases using OpenMP.
#   This exploits multi-core parallelism while respecting time-step
#   dependencies (the time loop itself remains sequential).
# - Finally, simplify and rename the scheduled procedure back to
#   "kernel_jacobi_2d" so that the generated C function has the
#   expected name used by the driver.
# ----------------------------------------------------------------------

kernel_jacobi_2d = kernel_jacobi_2d_base

# Tile sizes for the spatial dimensions. These can be tuned for the
# cache hierarchy of the target machine. They are compile-time constants
# from Exo's perspective.
TI = 32
TJ = 32

# Grab the original spatial loops before transformation. We get
# separate cursors for the B-update and A-update loops, and Exo will
# automatically forward them across transformations.
i_loops = kernel_jacobi_2d.find_all("for i in _:_")
j_loops = kernel_jacobi_2d.find_all("for j in _:_")

# i_loops[0] / j_loops[0] : B-update loops
# i_loops[1] / j_loops[1] : A-update loops
i_B = i_loops[0]
i_A = i_loops[1]
j_B = j_loops[0]
j_A = j_loops[1]

# -----------------------------
# Tile the B-update loops
# -----------------------------
kernel_jacobi_2d = divide_loop(
    kernel_jacobi_2d,
    i_B,
    TI,
    ["io_B", "ii_B"],
    tail="guard",
)
kernel_jacobi_2d = divide_loop(
    kernel_jacobi_2d,
    j_B,
    TJ,
    ["jo_B", "ji_B"],
    tail="guard",
)

# -----------------------------
# Tile the A-update loops
# -----------------------------
kernel_jacobi_2d = divide_loop(
    kernel_jacobi_2d,
    i_A,
    TI,
    ["io_A", "ii_A"],
    tail="guard",
)
kernel_jacobi_2d = divide_loop(
    kernel_jacobi_2d,
    j_A,
    TJ,
    ["jo_A", "ji_A"],
    tail="guard",
